package android.view;import android.content.Context;import android.content.res.Resources;import android.os.Handler;import android.os.Looper;import java.util.ArrayList;import java.util.List;
public class View implements ViewParent {
 public static final int VISIBLE=0,INVISIBLE=4,GONE=8,NO_ID=-1; private final Context context; private int id=NO_ID,visibility=VISIBLE;private ViewParent parent;private boolean attached;private ViewTreeObserver observer=new ViewTreeObserver();private final List<OnAttachStateChangeListener> attach=new ArrayList<OnAttachStateChangeListener>();public int visibilityWrites,invalidations;
 public interface OnAttachStateChangeListener{void onViewAttachedToWindow(View v);void onViewDetachedFromWindow(View v);}
 public View(Context c){context=c;}public Context getContext(){return context;}public Resources getResources(){return context.getResources();}public int getId(){return id;}public void setId(int x){id=x;}public int getVisibility(){return visibility;}public void setVisibility(int v){Looper.requireMain();visibility=v;visibilityWrites++;}public boolean isShown(){return visibility==VISIBLE&&(!(parent instanceof View)||((View)parent).isShown());}public void requestLayout(){invalidations++;}public void invalidate(){invalidations++;}public void postInvalidate(){invalidations++;}public boolean post(Runnable r){return new Handler().post(r);}public boolean postDelayed(Runnable r,long d){return new Handler().postDelayed(r,d);}public void postOnAnimation(Runnable r){new Handler().post(r);}public boolean removeCallbacks(Runnable r){new Handler().removeCallbacks(r);return true;}
 public boolean isAttachedToWindow(){return attached;}public Object getWindowToken(){return attached?this:null;}public ViewParent getParent(){return parent;}public void setParent(ViewParent p){parent=p;}public View getRootView(){return parent instanceof View?((View)parent).getRootView():this;}public ViewTreeObserver getViewTreeObserver(){return getRootView()==this?observer:getRootView().getViewTreeObserver();}
 @SuppressWarnings("unchecked") public <T extends View>T findViewById(int v){return id==v?(T)this:null;}
 public void addOnAttachStateChangeListener(OnAttachStateChangeListener l){attach.add(l);}public void removeOnAttachStateChangeListener(OnAttachStateChangeListener l){attach.remove(l);}public int attachListeners(){return attach.size();}
 public void attach(){if(attached)return;attached=true;if(!observer.isAlive())observer=new ViewTreeObserver();for(OnAttachStateChangeListener l:new ArrayList<OnAttachStateChangeListener>(attach))l.onViewAttachedToWindow(this);}
 public void detach(){if(!attached)return;attached=false;for(OnAttachStateChangeListener l:new ArrayList<OnAttachStateChangeListener>(attach))l.onViewDetachedFromWindow(this);if(getRootView()==this)observer.kill();}
}
